// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface SettingsSectionsOut {
  shortcut: string;
  /** False: the caller sent no token (the login screen), so only the This terminal tier */
  signed_in: boolean;
  tiers: SettingsTierOut[];
}

export interface SettingsTierOut {
  tier: "personal" | "facility" | "system" | "terminal";
  label: string;
  sections: SettingsSectionOut[];
}

export interface SettingsSectionOut {
  key: string;
  label: string;
  screen: string;
  danger: boolean;
  /** Also before login: the login screen's Settings button opens it (it writes nothing on the server) */
  before_login: boolean;
  endpoints: string[];
}

export interface MyPreferencesOut {
  theme: "Light" | "DarkHighContrast";
  language: "en" | "ur";
  ui_scale_pct: number;
  /** How a set of documents (the MSDS inspection pack) downloads: Separate = a button per document, one PDF each; Combined = one button, one PDF with all of them */
  pdf_download: "Separate" | "Combined";
  /** Anything else the frontend stores for this user */
  extra: Record<string, unknown>;
  /** Null until the user saves preferences for the first time */
  updated_at: string | null;
}

export interface PreferencesIn {
  theme?: "Light" | "DarkHighContrast" | null;
  language?: "en" | "ur" | null;
  /** Shared keyboard/Settings zoom state, bounded to 100–250%; Ctrl/Cmd +, -, 0 */
  ui_scale_pct?: number | null;
  /** A set of documents (the MSDS inspection pack): Separate = a download button per document, one PDF each (default); Combined = one button, one PDF with all of them */
  pdf_download?: "Separate" | "Combined" | null;
  /** Free-form UI state (e.g. last workspace, column widths); max 16 KB */
  extra?: Record<string, unknown> | null;
}

export interface ChangePasswordIn {
  current_password: string;
  new_password: string;
}

export interface TokenPair {
  access_token: string;
  /** Always bearer */
  token_type: string;
  /** Access token lifetime in seconds */
  expires_in: number;
  refresh_token: string;
  refresh_expires_in: number;
}

export interface SettingOut {
  key: string;
  /** The setting's JSON value (number, boolean, text, list ...) */
  value: unknown;
  description: string | null;
  /** A control setting: an Owner changes it or approves the change */
  is_control: boolean;
  updated_at: string;
}

export interface SettingIn {
  /** JSON value of the same type as the current one */
  value: unknown;
}

export interface SettingRowOut {
  key: string;
  /** The new JSON value */
  value_jsonb: unknown;
  description: string | null;
  updated_at: string;
  row_version: number;
}

export interface ChangeRequestIn {
  kind: "Setting" | "UserRoles" | "RolePermissions";
  setting_key?: string | null;
  /** kind UserRoles: the user (GET /admin/users) */
  target_user_id?: number | null;
  target_role_code?: string | null;
  /** Setting: the new value; UserRoles: role codes; RolePermissions: permission codes */
  requested_value: unknown;
  reason: string;
}

export interface AdminChangeRequestOut {
  change_request_id: number;
  kind: "Setting" | "UserRoles" | "RolePermissions";
  setting_key: string | null;
  target_user_id: number | null;
  target_role_code: string | null;
  requested_value: unknown;
  current_value: unknown | null;
  reason: string;
  status: "Pending" | "Applied" | "Rejected" | "Cancelled";
  approval_request_id: number | null;
  requested_by: number;
  requested_by_name: string;
  requested_at: string;
  decided_at: string | null;
}

export interface UserListItemOut {
  user_id: number;
  username: string;
  display_name: string;
  employee_id: number | null;
  is_active: boolean;
  must_change_pw: boolean;
  last_login_at: string | null;
